/**
 * IaC Generation (v4 Requirement 3)
 * 
 * Generates Terraform for pipeline resources. Plan-only by default.
 * Never runs apply autonomously. Least-privilege IAM scoping.
 */

'use strict';

function generateTerraform(ir) {
  const platform = ir.target_platform;
  switch (platform) {
    case 'aws': return generateAWSTerraform(ir);
    case 'databricks': return generateDatabricksTerraform(ir);
    case 'gcp': return generateGCPTerraform(ir);
    default: return generateAWSTerraform(ir);
  }
}

function generateAWSTerraform(ir) {
  return `# ${ir.name} — AWS Infrastructure
# Generated by EADD. Review before applying.
# Run: terraform plan (NEVER auto-apply)

variable "pipeline_name" { default = "${ir.name}" }
variable "region" { default = "us-east-1" }

provider "aws" { region = var.region }

resource "aws_s3_bucket" "data_lake" {
  bucket = "\${var.pipeline_name}-data-lake"
  tags   = { ManagedBy = "eadd", Pipeline = var.pipeline_name }
}

resource "aws_s3_bucket" "scripts" {
  bucket = "\${var.pipeline_name}-scripts"
  tags   = { ManagedBy = "eadd" }
}

# Least-privilege IAM role (only this pipeline's buckets)
resource "aws_iam_role" "pipeline_role" {
  name = "\${var.pipeline_name}-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = { Service = ["glue.amazonaws.com", "lambda.amazonaws.com"] }
    }]
  })
}

resource "aws_iam_role_policy" "pipeline_policy" {
  name = "\${var.pipeline_name}-policy"
  role = aws_iam_role.pipeline_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = ["s3:GetObject", "s3:PutObject", "s3:ListBucket"]
        Resource = [
          aws_s3_bucket.data_lake.arn,
          "\${aws_s3_bucket.data_lake.arn}/*",
          aws_s3_bucket.scripts.arn,
          "\${aws_s3_bucket.scripts.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = ["glue:StartJobRun", "glue:GetJobRun"]
        Resource = "arn:aws:glue:\${var.region}:*:job/\${var.pipeline_name}*"
      }
    ]
  })
}

output "data_lake_bucket" { value = aws_s3_bucket.data_lake.id }
output "role_arn" { value = aws_iam_role.pipeline_role.arn }
`;
}

function generateDatabricksTerraform(ir) {
  return `# ${ir.name} — Azure/Databricks Infrastructure
variable "pipeline_name" { default = "${ir.name}" }
variable "resource_group" { default = "eadd-rg" }
variable "location" { default = "eastus" }

provider "azurerm" { features {} }

resource "azurerm_storage_account" "datalake" {
  name                     = replace(var.pipeline_name, "_", "")
  resource_group_name      = var.resource_group
  location                 = var.location
  account_tier             = "Standard"
  account_replication_type = "LRS"
  is_hns_enabled           = true
}

resource "azurerm_storage_container" "bronze" {
  name                  = "bronze"
  storage_account_name  = azurerm_storage_account.datalake.name
  container_access_type = "private"
}

resource "azurerm_storage_container" "silver" {
  name                  = "silver"
  storage_account_name  = azurerm_storage_account.datalake.name
  container_access_type = "private"
}

resource "azurerm_storage_container" "gold" {
  name                  = "gold"
  storage_account_name  = azurerm_storage_account.datalake.name
  container_access_type = "private"
}
`;
}

function generateGCPTerraform(ir) {
  return `# ${ir.name} — GCP Infrastructure
variable "project_id" {}
variable "region" { default = "us-central1" }
variable "pipeline_name" { default = "${ir.name}" }

provider "google" { project = var.project_id; region = var.region }

resource "google_storage_bucket" "bronze" {
  name     = "\${var.pipeline_name}-bronze"
  location = var.region
}

resource "google_bigquery_dataset" "silver" {
  dataset_id = "silver"
  location   = var.region
}

resource "google_bigquery_dataset" "gold" {
  dataset_id = "gold"
  location   = var.region
}

resource "google_service_account" "pipeline" {
  account_id   = var.pipeline_name
  display_name = "Pipeline: \${var.pipeline_name}"
}

resource "google_project_iam_member" "bq" {
  project = var.project_id
  role    = "roles/bigquery.dataEditor"
  member  = "serviceAccount:\${google_service_account.pipeline.email}"
}

resource "google_project_iam_member" "gcs" {
  project = var.project_id
  role    = "roles/storage.objectAdmin"
  member  = "serviceAccount:\${google_service_account.pipeline.email}"
}
`;
}

module.exports = { generateTerraform };
